CREATE TABLE suppliers(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),code TEXT NOT NULL CHECK(length(trim(code)) BETWEEN 1 AND 60),created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,code),UNIQUE(id,store_id));
CREATE TABLE supplier_versions(supplier_id TEXT NOT NULL REFERENCES suppliers(id),store_id TEXT NOT NULL REFERENCES stores(id),version INTEGER NOT NULL CHECK(version>=1),sequence INTEGER NOT NULL CHECK(sequence>=1),name TEXT NOT NULL,contact_label TEXT,contact_method TEXT,address_note TEXT,scope_note TEXT NOT NULL,settlement_note TEXT,source_note TEXT NOT NULL,source_reference TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('active','inactive')),reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(supplier_id,version),UNIQUE(supplier_id,version,store_id),UNIQUE(store_id,sequence));
CREATE TABLE purchase_requests(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),serial INTEGER NOT NULL CHECK(serial>=1),purchase_number TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(id,store_id),UNIQUE(store_id,serial),UNIQUE(store_id,purchase_number));
CREATE TABLE purchase_versions(id TEXT PRIMARY KEY,request_id TEXT NOT NULL,store_id TEXT NOT NULL,version INTEGER NOT NULL CHECK(version>=1),base_sequence INTEGER NOT NULL CHECK(base_sequence>=0),supplier_id TEXT NOT NULL,supplier_version INTEGER NOT NULL,title TEXT NOT NULL,purpose_note TEXT NOT NULL,source_note TEXT NOT NULL,source_reference TEXT NOT NULL,expected_date TEXT,items_json TEXT NOT NULL CHECK(json_valid(items_json)),total_cents INTEGER NOT NULL CHECK(typeof(total_cents)='integer' AND total_cents BETWEEN 0 AND 1000000000000),currency TEXT NOT NULL CHECK(currency='CNY'),reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(request_id,version),FOREIGN KEY(request_id,store_id) REFERENCES purchase_requests(id,store_id),FOREIGN KEY(supplier_id,supplier_version,store_id) REFERENCES supplier_versions(supplier_id,version,store_id));
CREATE TABLE purchase_events(id TEXT PRIMARY KEY,request_id TEXT NOT NULL REFERENCES purchase_requests(id),version_id TEXT NOT NULL REFERENCES purchase_versions(id),store_id TEXT NOT NULL REFERENCES stores(id),revision INTEGER NOT NULL CHECK(revision>=1),sequence INTEGER NOT NULL CHECK(sequence>=1),action TEXT NOT NULL CHECK(action IN('create','revise','submit','approve','reject','reopen','order','cancel')),status TEXT NOT NULL CHECK(status=CASE action WHEN 'submit' THEN 'submitted' WHEN 'approve' THEN 'approved' WHEN 'reject' THEN 'rejected' WHEN 'order' THEN 'ordered' WHEN 'cancel' THEN 'cancelled' ELSE 'draft' END),product_basis_json TEXT NOT NULL CHECK(json_valid(product_basis_json)),decision_basis TEXT NOT NULL,ordered_at TEXT,order_reference TEXT,note TEXT NOT NULL,reason TEXT NOT NULL,next_step TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(request_id,revision),UNIQUE(store_id,sequence),CHECK((action='order' AND ordered_at IS NOT NULL AND order_reference IS NOT NULL) OR(action<>'order' AND ordered_at IS NULL AND order_reference IS NULL)));
CREATE VIEW supplier_current AS SELECT v.* FROM supplier_versions v WHERE version=(SELECT max(version) FROM supplier_versions WHERE supplier_id=v.supplier_id);
CREATE VIEW purchase_current AS SELECT e.* FROM purchase_events e WHERE revision=(SELECT max(revision) FROM purchase_events WHERE request_id=e.request_id);
CREATE VIEW procurement_journal AS SELECT supplier_id||':'||version id,store_id,sequence,created_at,'supplier' kind FROM supplier_versions UNION ALL SELECT id,store_id,sequence,created_at,'purchase' FROM purchase_events;
CREATE VIEW purchase_product_basis AS SELECT v.id version_id,coalesce((SELECT json_group_array(json_object('product_id',a.product_id,'version',a.version,'rowid',a.source_rowid)) FROM (SELECT DISTINCT p.product_id,p.version,p.rowid source_rowid FROM json_each(v.items_json) x JOIN retail_product_versions p ON p.product_id=json_extract(x.value,'$.product_id') AND p.version=(SELECT max(version) FROM retail_product_versions WHERE product_id=p.product_id) ORDER BY p.product_id) a),'[]') basis_json FROM purchase_versions v;
CREATE VIEW purchase_context AS SELECT r.*,e.version_id,e.revision,e.status,v.version,v.supplier_id,v.supplier_version,v.title,
CASE WHEN s.status='active' AND s.version=v.supplier_version AND NOT EXISTS(SELECT 1 FROM json_each(v.items_json) x WHERE NOT EXISTS(SELECT 1 FROM retail_product_versions p WHERE p.product_id=json_extract(x.value,'$.product_id') AND p.version=json_extract(x.value,'$.product_version') AND p.version=(SELECT max(version) FROM retail_product_versions WHERE product_id=p.product_id) AND p.store_id=r.store_id AND p.status='active' AND p.category<>'service')) THEN 1 ELSE 0 END source_valid
FROM purchase_requests r JOIN purchase_current e ON e.request_id=r.id JOIN purchase_versions v ON v.id=e.version_id JOIN supplier_current s ON s.supplier_id=v.supplier_id;
CREATE TRIGGER suppliers_no_update BEFORE UPDATE ON suppliers BEGIN SELECT RAISE(ABORT,'procurement immutable'); END;
CREATE TRIGGER suppliers_no_delete BEFORE DELETE ON suppliers BEGIN SELECT RAISE(ABORT,'procurement immutable'); END;
CREATE TRIGGER suppliers_actor BEFORE INSERT ON suppliers WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND coalesce(s.must_change_password,0)=0 AND u.role IN( 'manager' )) BEGIN SELECT RAISE(ABORT,'procurement actor/time'); END;
CREATE TRIGGER supplier_versions_no_update BEFORE UPDATE ON supplier_versions BEGIN SELECT RAISE(ABORT,'procurement immutable'); END;
CREATE TRIGGER supplier_versions_no_delete BEFORE DELETE ON supplier_versions BEGIN SELECT RAISE(ABORT,'procurement immutable'); END;
CREATE TRIGGER supplier_versions_actor BEFORE INSERT ON supplier_versions WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND coalesce(s.must_change_password,0)=0 AND u.role IN( 'manager' )) BEGIN SELECT RAISE(ABORT,'procurement actor/time'); END;
CREATE TRIGGER purchase_requests_no_update BEFORE UPDATE ON purchase_requests BEGIN SELECT RAISE(ABORT,'procurement immutable'); END;
CREATE TRIGGER purchase_requests_no_delete BEFORE DELETE ON purchase_requests BEGIN SELECT RAISE(ABORT,'procurement immutable'); END;
CREATE TRIGGER purchase_requests_actor BEFORE INSERT ON purchase_requests WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND coalesce(s.must_change_password,0)=0 AND u.role IN('manager','reception')) BEGIN SELECT RAISE(ABORT,'procurement actor/time'); END;
CREATE TRIGGER purchase_versions_no_update BEFORE UPDATE ON purchase_versions BEGIN SELECT RAISE(ABORT,'procurement immutable'); END;
CREATE TRIGGER purchase_versions_no_delete BEFORE DELETE ON purchase_versions BEGIN SELECT RAISE(ABORT,'procurement immutable'); END;
CREATE TRIGGER purchase_versions_actor BEFORE INSERT ON purchase_versions WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND coalesce(s.must_change_password,0)=0 AND u.role IN('manager','reception')) BEGIN SELECT RAISE(ABORT,'procurement actor/time'); END;
CREATE TRIGGER purchase_events_no_update BEFORE UPDATE ON purchase_events BEGIN SELECT RAISE(ABORT,'procurement immutable'); END;
CREATE TRIGGER purchase_events_no_delete BEFORE DELETE ON purchase_events BEGIN SELECT RAISE(ABORT,'procurement immutable'); END;
CREATE TRIGGER purchase_events_actor BEFORE INSERT ON purchase_events WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND coalesce(s.must_change_password,0)=0 AND u.role IN('manager','reception')) BEGIN SELECT RAISE(ABORT,'procurement actor/time'); END;
CREATE TRIGGER supplier_version_ready BEFORE INSERT ON supplier_versions WHEN NEW.version<>coalesce((SELECT max(version)+1 FROM supplier_versions WHERE supplier_id=NEW.supplier_id),1) OR NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM procurement_journal WHERE store_id=NEW.store_id),1) OR EXISTS(SELECT 1 FROM procurement_journal WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR NOT EXISTS(SELECT 1 FROM suppliers WHERE id=NEW.supplier_id AND store_id=NEW.store_id AND created_at<=NEW.created_at AND (NEW.version>1 OR created_at=NEW.created_at AND created_by=NEW.created_by)) BEGIN SELECT RAISE(ABORT,'procurement supplier source/version'); END;
CREATE TRIGGER purchase_root_ready BEFORE INSERT ON purchase_requests WHEN NEW.serial<>coalesce((SELECT max(serial)+1 FROM purchase_requests WHERE store_id=NEW.store_id),1) OR length(trim(NEW.purchase_number)) NOT BETWEEN 1 AND 100 BEGIN SELECT RAISE(ABORT,'procurement purchase identity'); END;
CREATE TRIGGER purchase_version_ready BEFORE INSERT ON purchase_versions WHEN NEW.version<>coalesce((SELECT max(version)+1 FROM purchase_versions WHERE request_id=NEW.request_id),1) OR NEW.base_sequence<>coalesce((SELECT max(sequence) FROM procurement_journal WHERE store_id=NEW.store_id),0) OR EXISTS(SELECT 1 FROM procurement_journal WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM purchase_current WHERE request_id=NEW.request_id AND status<>'draft') OR NEW.expected_date IS NOT NULL AND(length(NEW.expected_date)<>10 OR strftime('%Y-%m-%d',NEW.expected_date) IS NOT NEW.expected_date OR date(NEW.expected_date,'+0 days') IS NOT NEW.expected_date) OR NOT EXISTS(SELECT 1 FROM suppliers s JOIN supplier_versions v ON v.supplier_id=s.id WHERE s.id=NEW.supplier_id AND s.store_id=NEW.store_id AND v.version=NEW.supplier_version AND v.created_at<=NEW.created_at) BEGIN SELECT RAISE(ABORT,'procurement fixed request source/version'); END;
CREATE TRIGGER purchase_items_shape BEFORE INSERT ON purchase_versions WHEN json_type(NEW.items_json) IS NOT 'array' OR json_array_length(NEW.items_json) NOT BETWEEN 1 AND 50 OR EXISTS(SELECT 1 FROM json_each(NEW.items_json) x WHERE x.type<>'object' OR (SELECT count(*) FROM json_each(x.value))<>6 OR EXISTS(SELECT 1 FROM json_each(x.value) WHERE key NOT IN('position','product_id','product_version','quantity','unit_price_cents','note')) OR json_type(x.value,'$.position') IS NOT 'integer' OR json_extract(x.value,'$.position')<>x.key+1 OR json_type(x.value,'$.product_id') IS NOT 'text' OR json_type(x.value,'$.product_version') IS NOT 'integer' OR json_type(x.value,'$.quantity') IS NOT 'integer' OR json_extract(x.value,'$.quantity') NOT BETWEEN 1 AND 999 OR json_type(x.value,'$.unit_price_cents') IS NOT 'integer' OR json_extract(x.value,'$.unit_price_cents') NOT BETWEEN 0 AND 1000000000 OR (json_type(x.value,'$.note') IS NOT 'null' AND json_type(x.value,'$.note') IS NOT 'text') OR length(json_extract(x.value,'$.note'))>1000 OR NOT EXISTS(SELECT 1 FROM retail_product_versions p WHERE p.product_id=json_extract(x.value,'$.product_id') AND p.version=json_extract(x.value,'$.product_version') AND p.store_id=NEW.store_id AND p.category<>'service' AND p.created_at<=NEW.created_at)) OR NEW.total_cents IS NOT (SELECT sum(json_extract(value,'$.quantity')*json_extract(value,'$.unit_price_cents')) FROM json_each(NEW.items_json)) BEGIN SELECT RAISE(ABORT,'procurement actual product quantities/prices'); END;
CREATE TRIGGER purchase_event_ready BEFORE INSERT ON purchase_events BEGIN
SELECT CASE WHEN NEW.revision<>coalesce((SELECT max(revision)+1 FROM purchase_events WHERE request_id=NEW.request_id),1) OR NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM procurement_journal WHERE store_id=NEW.store_id),1) OR EXISTS(SELECT 1 FROM procurement_journal WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR NOT EXISTS(SELECT 1 FROM purchase_requests r JOIN purchase_versions v ON v.request_id=r.id WHERE r.id=NEW.request_id AND r.store_id=NEW.store_id AND v.id=NEW.version_id AND v.version=(SELECT max(version) FROM purchase_versions WHERE request_id=r.id) AND v.created_at<=NEW.created_at) OR NEW.product_basis_json IS NOT (SELECT basis_json FROM purchase_product_basis WHERE version_id=NEW.version_id) THEN RAISE(ABORT,'procurement current source/journal') END;
SELECT CASE WHEN NOT(NEW.action='create' AND NEW.revision=1 AND EXISTS(SELECT 1 FROM purchase_requests r JOIN purchase_versions v ON v.request_id=r.id WHERE r.id=NEW.request_id AND v.id=NEW.version_id AND v.version=1 AND v.created_at=r.created_at AND NEW.created_at=r.created_at AND v.created_by=r.created_by AND NEW.created_by=r.created_by AND v.base_sequence+1=NEW.sequence) OR NEW.action='revise' AND EXISTS(SELECT 1 FROM purchase_current old JOIN purchase_versions ov ON ov.id=old.version_id JOIN purchase_versions v ON v.id=NEW.version_id WHERE old.request_id=NEW.request_id AND old.status='draft' AND v.version=ov.version+1 AND v.base_sequence+1=NEW.sequence AND v.created_at=NEW.created_at AND v.created_by=NEW.created_by) OR EXISTS(SELECT 1 FROM purchase_current old WHERE old.request_id=NEW.request_id AND old.version_id=NEW.version_id AND(NEW.action='submit' AND old.status='draft' OR NEW.action IN('approve','reject') AND old.status='submitted' OR NEW.action='reopen' AND old.status IN('approved','rejected') OR NEW.action='order' AND old.status='approved' OR NEW.action='cancel' AND old.status IN('draft','submitted','approved','rejected')))) THEN RAISE(ABORT,'procurement explicit transition') END;
SELECT CASE WHEN NEW.action IN('approve','reject') AND NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.created_by AND role='manager') THEN RAISE(ABORT,'procurement commercial approver') END;
SELECT CASE WHEN NEW.action IN('submit','approve','order') AND NOT EXISTS(SELECT 1 FROM purchase_versions v JOIN supplier_current s ON s.supplier_id=v.supplier_id WHERE v.id=NEW.version_id AND s.version=v.supplier_version AND s.status='active' AND NOT EXISTS(SELECT 1 FROM json_each(v.items_json) x WHERE NOT EXISTS(SELECT 1 FROM retail_product_versions p WHERE p.product_id=json_extract(x.value,'$.product_id') AND p.version=json_extract(x.value,'$.product_version') AND p.version=(SELECT max(version) FROM retail_product_versions WHERE product_id=p.product_id) AND p.status='active' AND p.store_id=NEW.store_id AND p.category<>'service'))) THEN RAISE(ABORT,'procurement original supplier/product source held') END;
SELECT CASE WHEN NEW.action='order' AND(length(NEW.ordered_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.ordered_at) IS NOT NEW.ordered_at OR NEW.ordered_at>NEW.created_at OR NEW.ordered_at<(SELECT created_at FROM purchase_current WHERE request_id=NEW.request_id) OR length(trim(NEW.order_reference)) NOT BETWEEN 1 AND 120 OR length(NEW.order_reference)>120 OR EXISTS(SELECT 1 FROM purchase_events e JOIN purchase_versions ov ON ov.id=e.version_id JOIN purchase_versions v ON v.id=NEW.version_id WHERE e.action='order' AND e.store_id=NEW.store_id AND e.order_reference=NEW.order_reference AND ov.supplier_id=v.supplier_id)) THEN RAISE(ABORT,'procurement actual order source/time/reference') END;
END;
CREATE TRIGGER supplier_versions_text BEFORE INSERT ON supplier_versions WHEN length(trim(NEW.name)) NOT BETWEEN 1 AND 120 OR length(NEW.name)>120 OR length(trim(NEW.scope_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.scope_note)>2000 OR length(trim(NEW.source_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.source_note)>2000 OR length(trim(NEW.source_reference)) NOT BETWEEN 1 AND 1000 OR length(NEW.source_reference)>1000 OR length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 BEGIN SELECT RAISE(ABORT,'procurement actual source fields'); END;
CREATE TRIGGER purchase_versions_text BEFORE INSERT ON purchase_versions WHEN length(trim(NEW.title)) NOT BETWEEN 1 AND 120 OR length(NEW.title)>120 OR length(trim(NEW.purpose_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.purpose_note)>2000 OR length(trim(NEW.source_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.source_note)>2000 OR length(trim(NEW.source_reference)) NOT BETWEEN 1 AND 1000 OR length(NEW.source_reference)>1000 OR length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 BEGIN SELECT RAISE(ABORT,'procurement actual source fields'); END;
CREATE TRIGGER purchase_events_text BEFORE INSERT ON purchase_events WHEN length(trim(NEW.decision_basis)) NOT BETWEEN 1 AND 2000 OR length(NEW.decision_basis)>2000 OR length(trim(NEW.note)) NOT BETWEEN 1 AND 2000 OR length(NEW.note)>2000 OR length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 OR length(trim(NEW.next_step)) NOT BETWEEN 1 AND 2000 OR length(NEW.next_step)>2000 BEGIN SELECT RAISE(ABORT,'procurement actual source fields'); END;
CREATE TRIGGER supplier_contact_label_text BEFORE INSERT ON supplier_versions WHEN NEW.contact_label IS NOT NULL AND(length(trim(NEW.contact_label)) NOT BETWEEN 1 AND 120 OR length(NEW.contact_label)>120) BEGIN SELECT RAISE(ABORT,'procurement known contact/source'); END;
CREATE TRIGGER supplier_contact_method_text BEFORE INSERT ON supplier_versions WHEN NEW.contact_method IS NOT NULL AND(length(trim(NEW.contact_method)) NOT BETWEEN 1 AND 200 OR length(NEW.contact_method)>200) BEGIN SELECT RAISE(ABORT,'procurement known contact/source'); END;
CREATE TRIGGER supplier_address_note_text BEFORE INSERT ON supplier_versions WHEN NEW.address_note IS NOT NULL AND(length(trim(NEW.address_note)) NOT BETWEEN 1 AND 1000 OR length(NEW.address_note)>1000) BEGIN SELECT RAISE(ABORT,'procurement known contact/source'); END;
CREATE TRIGGER supplier_settlement_note_text BEFORE INSERT ON supplier_versions WHEN NEW.settlement_note IS NOT NULL AND(length(trim(NEW.settlement_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.settlement_note)>2000) BEGIN SELECT RAISE(ABORT,'procurement known contact/source'); END;
CREATE TRIGGER procurement_product_unit_lock BEFORE INSERT ON retail_product_versions WHEN EXISTS(SELECT 1 FROM purchase_events e JOIN purchase_versions v ON v.id=e.version_id JOIN json_each(v.items_json) x JOIN retail_product_versions p ON p.product_id=json_extract(x.value,'$.product_id') AND p.version=json_extract(x.value,'$.product_version') WHERE e.action='order' AND p.product_id=NEW.product_id AND (p.unit<>NEW.unit OR p.category<>NEW.category)) BEGIN SELECT RAISE(ABORT,'procurement ordered product unit/category locked'); END;
